package main

import "fmt"

type Rectangle struct {
	Width  float64
	Height float64
}

func (r Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r Rectangle) Perimeter() float64 {
	return 2 * (r.Width + r.Height)
}

func (r *Rectangle) Scale(factor float64) {
	r.Width *= factor
	r.Height *= factor
}

type BankAccount struct {
	Owner   string
	Balance float64
}

func (b *BankAccount) Deposit(amount float64) {
	if amount > 0 {
		b.Balance += amount
	}
}

func (b *BankAccount) Withdraw(amount float64) bool {
	if amount > b.Balance {
		return false
	}
	b.Balance -= amount
	return true
}

func (b BankAccount) String() string {
	return fmt.Sprintf("Account[%s]: Rp %.2f", b.Owner, b.Balance)
}

func main() {
	// Rectangle methods
	rect := Rectangle{Width: 6, Height: 4}
	fmt.Printf("Area: %.1f\n", rect.Area())
	fmt.Printf("Perimeter: %.1f\n", rect.Perimeter())
	rect.Scale(2)
	fmt.Printf("After scale 2x: %.1f x %.1f\n", rect.Width, rect.Height)

	// BankAccount methods
	account := BankAccount{Owner: "Alice", Balance: 1_000_000}
	account.Deposit(500_000)
	success := account.Withdraw(200_000)
	fmt.Println(account)
	fmt.Println("Withdrawal success:", success)

	failed := account.Withdraw(5_000_000)
	fmt.Println("Large withdrawal success:", failed)
}
